use axbi_atomic_vector_component::{validation,benchmark,POINTS,CELLS};
use std::sync::atomic::Ordering;
fn prior(name:&str)->u64{std::env::var(name).expect("mandatory prior counter missing").parse().expect("invalid prior counter")}
fn main(){let args:Vec<String>=std::env::args().collect();assert_eq!(args.len(),5);assert_eq!(args[1],"--contract");assert_eq!(args[3],"--output");let c=std::fs::read_to_string(&args[2]).unwrap();assert!(c.contains("ATOMIC_VECTOR_001"));let pp=prior("AXBI_PRIOR_POINT_CALLS");let pc=prior("AXBI_PRIOR_PHOTON_CELLS");let pv=prior("AXBI_PRIOR_VALIDATION_POINT_CALLS");assert!(pp<=250000&&pc<=50000000&&pv<=50000);POINTS.store(pp,Ordering::SeqCst);CELLS.store(pc,Ordering::SeqCst);
 let result=std::panic::catch_unwind(||{assert!(pv+15000<=50000,"reserve validation quota");let (p,n,res)=validation();assert!(pv+p<=50000);let b=benchmark();let tp=POINTS.load(Ordering::SeqCst);let tc=CELLS.load(Ordering::SeqCst);let output=format!("{{\"validation\":\"PASS_EXACT_COMPONENT_PARITY\",\"validation_point_calls\":{p},\"validation_photon_cells\":{n},\"photon_count_residuals\":{res:?},\"prior_point_calls\":{pp},\"prior_photon_cells\":{pc},\"remote_point_calls\":{},\"remote_photon_cells\":{},\"total_point_calls\":{tp},\"total_photon_cells\":{tc},\"total_validation_point_calls\":{},\"benchmark\":{b},\"scientific_admission\":\"NOT_ISSUED\"}}",tp-pp,tc-pc,pv+p);std::fs::write(&args[4],output).unwrap();});println!("OBSERVED_COUNTERS point_calls={} photon_cells={}",POINTS.load(Ordering::SeqCst),CELLS.load(Ordering::SeqCst));if let Err(e)=result{std::panic::resume_unwind(e);}}
